package com.seaoftales.identity.controller;
import com.seaoftales.content.enums.Language; import com.seaoftales.identity.enums.*; import com.seaoftales.identity.service.IdentityService; import com.seaoftales.storage.*; import jakarta.servlet.http.*; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.authentication.dao.DaoAuthenticationProvider; import org.springframework.security.core.AuthenticationException; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.util.*;
@RestController @RequestMapping("/api") public class AuthController {private final IdentityService service; private final ImageStorageService imageStorage; private final AuthenticationManager manager; public AuthController(IdentityService s,ImageStorageService imageStorage,org.springframework.security.core.userdetails.UserDetailsService uds,org.springframework.security.crypto.password.PasswordEncoder enc){service=s;this.imageStorage=imageStorage;var p=new DaoAuthenticationProvider(uds);p.setPasswordEncoder(enc);manager=new ProviderManager(p);}
 private static final Logger log=LoggerFactory.getLogger(AuthController.class);
 @PostMapping("/auth/register") public ResponseEntity<?> register(@RequestBody Map<String,String>b){try{service.register(b.get("username"),b.get("email"),b.get("password"));log.info("POST /api/auth/register completed; returning HTTP 202 Accepted");return ResponseEntity.status(202).body(Map.of("requiresVerification",true,"email",b.get("email"),"type",OtpPurpose.REGISTRATION.name(),"message","Verification code sent."));}catch(RuntimeException e){log.error("POST /api/auth/register failed; exception type={}, message={}",e.getClass().getName(),e.getMessage(),e);return ResponseEntity.badRequest().body(Map.of("message",service.registrationError(e)));}}
 @PostMapping(value="/auth/register",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> registerMultipart(@RequestParam String username,@RequestParam String email,@RequestParam String password,@RequestPart(required=false) MultipartFile profilePicture){String reference=null;try{reference=profilePicture==null||profilePicture.isEmpty()?null:imageStorage.store(profilePicture,ImageUploadPolicy.PROFILE_PICTURE);service.register(username,email,password,reference);return ResponseEntity.status(202).body(Map.of("requiresVerification",true,"email",email,"type",OtpPurpose.REGISTRATION.name(),"message","Verification code sent."));}catch(IOException|RuntimeException e){if(reference!=null)imageStorage.delete(reference);return ResponseEntity.badRequest().body(Map.of("message",service.registrationError(e instanceof RuntimeException r?r:new IllegalArgumentException("Invalid image."))));}}
 @PostMapping("/auth/verify-otp") public ResponseEntity<?> verify(@RequestBody Map<String,String>b){try{service.verifyRegistration(b.get("email"),b.get("code"));return ResponseEntity.ok(Map.of("message","Registration complete."));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
 @PostMapping("/auth/resend-otp") public ResponseEntity<?> resend(@RequestBody Map<String,String>b){try{service.resend(b.get("email"),OtpPurpose.valueOf(b.getOrDefault("purpose","REGISTRATION")));return ResponseEntity.ok(Map.of("message","Verification code sent."));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String>b,HttpServletRequest req,HttpServletResponse res){try{var a=manager.authenticate(new UsernamePasswordAuthenticationToken(b.get("username"),b.get("password")));SecurityContextHolder.getContext().setAuthentication(a);new HttpSessionSecurityContextRepository().saveContext(SecurityContextHolder.getContext(),req,res);return ResponseEntity.ok(Map.of("username",a.getName(),"role",a.getAuthorities().iterator().next().getAuthority()));}catch(AuthenticationException e){return ResponseEntity.status(401).body(Map.of("message","Invalid credentials."));}}
 @GetMapping("/auth/me") public ResponseEntity<?> me(org.springframework.security.core.Authentication a){return a==null||!a.isAuthenticated()?ResponseEntity.status(401).body(Map.of("message","Authentication required.")):ResponseEntity.ok(Map.of("username",a.getName(),"role",a.getAuthorities().iterator().next().getAuthority()));}
 @PostMapping("/invitations/{type}") public ResponseEntity<?> invite(@PathVariable InvitationType type,@RequestBody(required=false) Map<String,String> body,HttpServletRequest request){if(type==InvitationType.EDITOR)return ResponseEntity.status(501).body(Map.of("message","Editor invitation email generation is unavailable until Editor registration is implemented."));try{String languageValue=body==null?null:body.get("language");if(!"ENGLISH".equals(languageValue)&&!"JAPANESE".equals(languageValue)&&!"KOREAN".equals(languageValue))return ResponseEntity.badRequest().body(Map.of("message","Please select a preferred language."));var language=Language.valueOf(languageValue);var invitation=service.createAuthorInvitation(body==null?null:body.get("email"),language,request.getHeader("Origin"));return invitationResponse(invitation);}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()==null?"Invitation could not be created.":e.getMessage()));}}
 @PostMapping("/invitations/author/resend") public ResponseEntity<?> resendAuthorInvitation(@RequestBody Map<String,String> body,HttpServletRequest request){try{return invitationResponse(service.resendAuthorInvitation(body.get("token"),request.getHeader("Origin")));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()==null?"Invitation email could not be resent.":e.getMessage()));}}
 private ResponseEntity<?> invitationResponse(IdentityService.CreatedInvitation invitation){return ResponseEntity.ok(Map.of("token",invitation.token(),"type","AUTHOR","expiresAt",invitation.expiresAt(),"used",invitation.used(),"recipientEmail",invitation.recipientEmail(),"preferredLanguage",invitation.preferredLanguage()==null?Language.JAPANESE:invitation.preferredLanguage(),"emailSent",invitation.emailSent()));}
 @GetMapping("/invitations/validate") public ResponseEntity<?> validate(@RequestParam String token,@RequestParam InvitationType type){try{var invitation=service.valid(token,type);return ResponseEntity.ok(Map.of("valid",true,"type",type,"preferredLanguage",invitation.getPreferredLanguage()==null?Language.JAPANESE:invitation.getPreferredLanguage()));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("valid",false,"message",e.getMessage()));}}
 @PostMapping("/auth/invitation-register") public ResponseEntity<?> invitationRegister(@RequestBody Map<String,String>b){try{if(!"AUTHOR".equals(b.get("type")))throw new IllegalArgumentException("Invalid invitation.");service.registerInvitation(b.get("token"),InvitationType.AUTHOR,b.get("username"),b.get("email"),b.get("password"),Language.valueOf(b.getOrDefault("language","")));return ResponseEntity.status(202).body(Map.of("message","Verification code sent."));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",service.registrationError(e)));}}
 @PostMapping(value="/auth/invitation-register",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> invitationRegisterMultipart(@RequestParam String token,@RequestParam String type,@RequestParam String username,@RequestParam String email,@RequestParam String password,@RequestParam String language,@RequestPart(required=false) MultipartFile profilePicture){String reference=null;try{reference=profilePicture==null||profilePicture.isEmpty()?null:imageStorage.store(profilePicture,ImageUploadPolicy.PROFILE_PICTURE);service.registerInvitation(token,InvitationType.valueOf(type),username,email,password,Language.valueOf(language),reference);return ResponseEntity.status(202).body(Map.of("message","Verification code sent."));}catch(IOException|RuntimeException e){if(reference!=null)imageStorage.delete(reference);return ResponseEntity.badRequest().body(Map.of("message",service.registrationError(e instanceof RuntimeException r?r:new IllegalArgumentException("Invalid image."))));}}
 @GetMapping("/identity/options") public Object options(){return Map.of("languages",Language.values());}
 @PostMapping("/auth/change-password") public ResponseEntity<?> change(@RequestBody Map<String,String>b,org.springframework.security.core.Authentication a){if(a==null||!a.isAuthenticated())return ResponseEntity.status(401).build();try{service.changePassword(a.getName(),b.get("currentPassword"),b.get("newPassword"));return ResponseEntity.noContent().build();}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
 @PostMapping("/auth/forgot-password") public ResponseEntity<?> forgot(@RequestBody Map<String,String>b){try{service.requestReset(b.get("identifier"));}catch(RuntimeException ignored){}return ResponseEntity.ok(Map.of("message","If an account exists for the supplied information, a verification code has been sent."));}
 @PostMapping("/auth/reset-password") public ResponseEntity<?> reset(@RequestBody Map<String,String>b){try{service.resetPassword(b.get("identifier"),b.get("code"),b.get("newPassword"));return ResponseEntity.noContent().build();}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
}
